{
  "scenarios": [
    {
      "id": "M09-01",
      "category": "用户更正先前陈述",
      "turns": [
        {
          "user": "我上周提到自己从2018年起一直服用降压药，但仔细回想后觉得不对，其实那是2019年才开始吃的，之前只是偶尔监测血压。"
        },
        {
          "assistant": "收到，已记录您关于开始服药时间的更正信息。"
        }
      ],
      "queries": [
        {
          "id": "Q1",
          "query": "请确认患者实际开始规律服用降压药物的具体年份是哪一年？",
          "expected_facts": [
            "患者在2019年开始规律服用降压药。",
            "患者在2018年并未规律服药，仅偶尔监测血压。"
          ],
          "required_groups": [
            ["2019年", "一九一九年"],
            ["开始", "起始", "启用"],
            ["规律服用", "按时吃药"]
          ]
        },
        {
          "id": "Q2",
          "query": "在2018年期间，该患者的血压管理方式是怎样的？",
          "expected_facts": [
            "患者在2018年期间仅偶尔监测血压。",
            "患者在2018年尚未开始规律服用降压药物。"
          ],
          "required_groups": [
            ["2018年", "二零一八年"],
            ["偶尔监测", "间断测量"],
            ["未规律服药", "没吃药"]
          ]
        }
      ]
    },
    {
      "id": "M09-02",
      "category": "用户更正先前陈述",
      "turns": [
        {
          "user": "之前我说我的过敏史是对花生严重过敏，但最近一次体检报告提醒我，其实我对的是芒果过敏，花生只是小时候误食过两次没事。"
        },
        {
          "assistant": "明白，已将您的过敏原记录更新为芒果，并备注花生无严重反应。"
        }
      ],
      "queries": [
        {
          "id": "Q1",
          "query": "根据最新更正，患者目前被确认的严重过敏原是哪种水果？",
          "expected_facts": [
            "患者对芒果存在严重过敏反应。",
            "患者此前误报的对花生过敏已被更正。"
          ],
          "required_groups": [
            ["芒果", "大芒果"],
            ["严重过敏", "重度过敏"],
            ["更正", "修正", "更新"]
          ]
        },
        {
          "id": "Q2",
          "query": "患者童年时期接触花生后的实际身体反应如何？",
          "expected_facts": [
            "患者小时候误食花生两次后没有发生不良反应。",
            "患者并非对花生过敏。"
          ],
          "required_groups": [
            ["小时候", "童年", "幼年"],
            ["误食", "吃过"],
            ["无反应", "没事", "正常"]
          ]
        }
      ]
    },
    {
      "id": "M09-03",
      "category": "用户更正先前陈述",
      "turns": [
        {
          "user": "我之前说手术是在北京做的，后来翻到病历发现记错了，那台阑尾炎切除手术其实是在上海的一家医院完成的，时间是2020年5月。"
        },
        {
          "assistant": "好的，已修正手术地点为上海，时间确认为2020年5月。"
        }
      ],
      "queries": [
        {
          "id": "Q1",
          "query": "患者接受阑尾炎切除手术的实际城市是哪里？",
          "expected_facts": [
            "患者的阑尾炎切除手术是在上海进行的。",
            "患者此前声称在北京手术的说法是错误的。"
          ],
          "required_groups": [
            ["上海", "沪"],
            ["阑尾炎切除", "切阑尾"],
            ["实际", "真实", "正确"]
          ]
        },
        {
          "id": "Q2",
          "query": "该次手术发生的具体月份和年份是什么？",
          "expected_facts": [
            "手术发生在2020年5月。",
            "患者曾错误记忆了手术地点。"
          ],
          "required_groups": [
            ["2020年", "二零二零年"],
            ["5月", "五月"],
            ["手术", "开刀"]
          ]
        }
      ]
    },
    {
      "id": "M09-04",
      "category": "用户更正先前陈述",
      "turns": [
        {
          "user": "刚才提到我父亲有糖尿病，但我刚和他确认过，他其实是高血压，糖尿病是我母亲的情况，而且她是在2015年确诊的。"
        },
        {
          "assistant": "收到，已区分父母双方的病史，父亲为高血压，母亲为2015年确诊的糖尿病。"
        }
      ],
      "queries": [
        {
          "id": "Q1",
          "query": "患者父亲的慢性病史实际上是什么疾病？",
          "expected_facts": [
            "患者父亲患有高血压。",
            "患者父亲并不患有糖尿病。"
          ],
          "required_groups": [
            ["父亲", "爸爸"],
            ["高血压", "血压高"],
            ["不患", "没有", "非"]
          ]
        },
        {
          "id": "Q2",
          "query": "患者母亲的糖尿病是在哪一年被确诊的？",
          "expected_facts": [
            "患者母亲于2015年被确诊患有糖尿病。",
            "此前将糖尿病归因于父亲是错误的。"
          ],
          "required_groups": [
            ["母亲", "妈妈"],
            ["2015年", "二零一五年"],
            ["确诊", "诊断"]
          ]
        }
      ]
    },
    {
      "id": "M09-05",
      "category": "用户更正先前陈述",
      "turns": [
        {
          "user": "我之前说戒烟已经三年了，但仔细算了一下日子，其实是从2021年1月才彻底戒掉的，之前那段时间只是减量，并没有完全停止。"
        },
        {
          "assistant": "了解，已将戒烟时间点修正为2021年1月，并标注此前为减量阶段。"
        }
      ],
      "queries": [
        {
          "id": "Q1",
          "query": "患者彻底停止吸烟的确切起始时间是什么时候？",
          "expected_facts": [
            "患者于2021年1月彻底戒烟。",
            "在此之前患者仅减少了吸烟量，并未完全停止。"
          ],
          "required_groups": [
            ["2021年1月", "二零二一年一月"],
            ["彻底戒烟", "完全停止"],
            ["减量", "少抽"]
          ]
        },
        {
          "id": "Q2",
          "query": "在2021年1月之前，患者的吸烟状态是怎样的？",
          "expected_facts": [
            "在2021年1月之前，患者处于减少吸烟量的状态。",
            "患者此前并未实现完全戒烟。"
          ],
          "required_groups": [
            ["2021年1月之前", "此前"],
            ["减少", "减量"],
            ["未完全停止", "没戒掉"]
          ]
        }
      ]
    },
    {
      "id": "M09-06",
      "category": "用户更正先前陈述",
      "turns": [
        {
          "user": "上次我说自己从未做过胃镜，但今天整理旧档案发现，其实在2017年因为胃痛做过一次检查，当时结果是浅表性胃炎。"
        },
        {
          "assistant": "收到，已补充2017年的胃镜检查记录及浅表性胃炎的诊断结果。"
        }
      ],
      "queries": [
        {
          "id": "Q1",
          "query": "患者实际上在哪一年进行过胃镜检查？",
          "expected_facts": [
            "患者在2017年进行过胃镜检查。",
            "患者此前声称从未做过胃镜是不准确的。"
          ],
          "required_groups": [
            ["2017年", "二零一七年"],
            ["胃镜", "胃镜检查"],
            ["做过", "进行过"]
          ]
        },
        {
          "id": "Q2",
          "query": "那次胃镜检查得出的具体医学结论是什么？",
          "expected_facts": [
            "2017年的胃镜检查结果显示为浅表性胃炎。",
            "患者曾因胃痛症状进行检查。"
          ],
          "required_groups": [
            ["浅表性胃炎", "轻度胃炎"],
            ["检查结果", "诊断"],
            ["胃痛", "胃部不适"]
          ]
        }
      ]
    },
    {
      "id": "M09-07",
      "category": "用户更正先前陈述",
      "turns": [
        {
          "user": "我之前说住在南方潮湿地区导致关节痛，但搬家记录显示我2018年就搬到了北方干燥城市，关节痛其实是在2019年冬天开始的，可能与受凉有关。"
        },
        {
          "assistant": "明白，已更新居住地变更时间为2018年，并将关节痛起始时间修正为2019年冬。"
        }
      ],
      "queries": [
        {
          "id": "Q1",
          "query": "患者何时完成了从南方到北方的居住地迁移？",
          "expected_facts": [
            "患者于2018年搬到了北方干燥城市。",
            "患者此前关于长期居住在南方的说法有误。"
          ],
          "required_groups": [
            ["2018年", "二零一八年"],
            ["搬到北方", "迁居北方"],
            ["干燥城市", "北方"]
          ]
        },
        {
          "id": "Q2",
          "query": "患者关节疼痛症状实际开始的时间段是何时？",
          "expected_facts": [
            "患者的关节痛始于2019年冬天。",
            "症状出现与居住环境改变后的受凉可能相关。"
          ],
          "required_groups": [
            ["2019年冬天", "二零一九年冬季"],
            ["关节痛", "关节疼"],
            ["开始", "发作"]
          ]
        }
      ]
    },
    {
      "id": "M09-08",
      "category": "用户更正先前陈述",
      "turns": [
        {
          "user": "刚才提到我弟弟有哮喘，但刚刚联系他确认，其实是他妹妹有哮喘，而且她是从小就有，我是记混了兄弟姐妹的顺序。"
        },
        {
          "assistant": "收到，已更正家族病史，确认患者妹妹自幼患有哮喘，弟弟无此病史。"
        }
      ],
      "queries": [
        {
          "id": "Q1",
          "query": "患者家中哪位亲属被确认患有哮喘？",
          "expected_facts": [
            "患者的妹妹患有哮喘。",
            "患者的弟弟并不患有哮喘。"
          ],
          "required_groups": [
            ["妹妹", "姐姐"],
            ["哮喘", "气喘"],
            ["弟弟", "兄弟"]
          ]
        },
        {
          "id": "Q2",
          "query": "这位患病亲属的哮喘病史是从什么时候开始的？",
          "expected_facts": [
            "患者的妹妹从小就有哮喘病史。",
            "此前将哮喘归因于弟弟是错误的。"
          ],
          "required_groups": [
            ["从小", "幼年", "儿时"],
            ["哮喘", "气喘"],
            ["妹妹", "姐妹"]
          ]
        }
      ]
    },
    {
      "id": "M09-09",
      "category": "用户更正先前陈述",
      "turns": [
        {
          "user": "我之前说对青霉素不过敏，但翻看旧病历发现2016年输液时出现过皮疹，医生当时记录为青霉素过敏，所以我应该是有过敏史的。"
        },
        {
          "assistant": "了解，已根据2016年病历记录，将您的青霉素过敏史更新为阳性。"
        }
      ],
      "queries": [
        {
          "id": "Q1",
          "query": "患者对青霉素的过敏状态应如何认定？",
          "expected_facts": [
            "患者对青霉素存在过敏史。",
            "患者此前声称不过敏的说法已被2016年的病历记录推翻。"
          ],
          "required_groups": [
            ["青霉素", "盘尼西林"],
            ["过敏", "过敏反应"],
            ["存在", "有"]
          ]
        },
        {
          "id": "Q2",
          "query": "支持患者青霉素过敏判断的关键历史事件发生在哪一年？",
          "expected_facts": [
            "2016年患者输液时出现皮疹并被记录为青霉素过敏。",
            "该事件证实了患者的过敏体质。"
          ],
          "required_groups": [
            ["2016年", "二零一六年"],
            ["皮疹", "皮肤反应"],
            ["输液", "打针"]
          ]
        }
      ]
    },
    {
      "id": "M09-10",
      "category": "用户更正先前陈述",
      "turns": [
        {
          "user": "之前我说每天喝两杯咖啡，但最近统计发现其实只喝一杯，另一杯是茶，而且这个习惯是从2022年开始调整的，以前确实喝两杯咖啡。"
        },
        {
          "assistant": "收到，已更新饮品摄入记录：2022年起调整为每日一杯咖啡加一杯茶。"
        }
      ],
      "queries": [
        {
          "id": "Q1",
          "query": "患者目前的日常咖啡因饮品摄入组合是什么？",
          "expected_facts": [
            "患者目前每天饮用一杯咖啡和一杯茶。",
            "患者此前声称每天喝两杯咖啡是不准确的。"
          ],
          "required_groups": [
            ["一杯咖啡", "一壶咖啡"],
            ["一杯茶", "一壶茶"],
            ["目前", "现在"]
          ]
        },
        {
          "id": "Q2",
          "query": "患者改变饮品习惯的具体时间节点是哪一年？",
          "expected_facts": [
            "患者从2022年开始调整饮品习惯。",
            "在2022年之前，患者每天饮用两杯咖啡。"
          ],
          "required_groups": [
            ["2022年", "二零二二年"],
            ["调整", "改变", "开始"],
            ["两杯咖啡", "双份咖啡"]
          ]
        }
      ]
    }
  ]
}
